import { mkdir, readFile, writeFile, rm, stat } from 'node:fs/promises';
import path from 'node:path';
import sharp from 'sharp';

const root = process.cwd();
const imageDir = path.join(root, 'public/assets/images');
await mkdir(imageDir, { recursive: true });
const sources = [
  ['wall-decor-front', 'wall-decor-front.jpeg'],
  ['wall-decor-right', 'wall-decor-right.png'],
  ['wall-decor-left', 'wall-decor-left.png'],
  ['wall-decor-close', 'wall-decor-close.png']
];

// Remove only assets generated by the former demo pipeline, never merchant uploads.
for (const name of ['product-main', 'product-detail', 'product-angle', 'lifestyle', 'video-poster']) {
  for (const ext of ['jpg', 'webp']) await rm(path.join(imageDir, `${name}.${ext}`), { force: true });
  await rm(path.join(imageDir, `thumb-${name}.webp`), { force: true });
}
await rm(path.join(root, 'public/assets/videos/decor-demo-placeholder.mp4'), { force: true });

let inputBytes = 0;
let webpBytes = 0;
for (const [name, source] of sources) {
  const input = path.join(root, 'assets-source', source);
  const pipeline = sharp(input).rotate().resize({ width: 1200, height: 900, fit: 'inside', withoutEnlargement: true });
  await pipeline.clone().webp({ quality: 80, effort: 6 }).toFile(path.join(imageDir, `${name}.webp`));
  await pipeline.clone().jpeg({ quality: 79, progressive: true, mozjpeg: true }).toFile(path.join(imageDir, `${name}.jpg`));
  await sharp(input).rotate().resize({ width: 240, height: 180, fit: 'inside', withoutEnlargement: true })
    .webp({ quality: 68, effort: 6 }).toFile(path.join(imageDir, `thumb-${name}.webp`));
  inputBytes += (await stat(input)).size;
  webpBytes += (await stat(path.join(imageDir, `${name}.webp`))).size;
}

const mark = await readFile(path.join(root, 'public/assets/brand/zestbd-mark.svg'));
await writeFile(path.join(root, 'public/favicon.svg'), mark);
for (const [name, size] of [['favicon-32.png', 32], ['apple-touch-icon.png', 180], ['icon-192.png', 192], ['icon-512.png', 512]]) {
  await sharp(mark).resize(size, size).png().toFile(path.join(root, 'public', name));
}
const iconPng = await sharp(mark).resize(32, 32).png().toBuffer();
const iconHeader = Buffer.alloc(22);
iconHeader.writeUInt16LE(1, 2);
iconHeader.writeUInt16LE(1, 4);
iconHeader[6] = 32;
iconHeader[7] = 32;
iconHeader.writeUInt16LE(1, 10);
iconHeader.writeUInt16LE(32, 12);
iconHeader.writeUInt32LE(iconPng.length, 14);
iconHeader.writeUInt32LE(22, 18);
await writeFile(path.join(root, 'public/favicon.ico'), Buffer.concat([iconHeader, iconPng]));
console.log(`Four uncropped product images: ${(inputBytes / 1024 / 1024).toFixed(2)} MB to ${(webpBytes / 1024).toFixed(0)} KB WebP (${(100 * (1 - webpBytes / inputBytes)).toFixed(1)}% smaller). Brand icons prepared.`);
